import{_ as i,a0 as a,w as l,s as p,I as e,x as t,a1 as s,A as r,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT x X-CMD","titleTemplate":false,"description":"Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170623 Chromebook Dual Boot How-to Ubuntu 17.04 GNOME and Chrome OS","title":"Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS","tag":"201707","desc":""},"relativePath":"201707/20170623 Chromebook Dual Boot How-to Ubuntu 17.04 GNOME and Chrome OS.md","filePath":"[post].md"}'),h={name:"201707/20170623 Chromebook Dual Boot How-to Ubuntu 17.04 GNOME and Chrome OS.md"};function m(b,o,d,C,g,k){const n=a("Link");return l(),p("div",null,[o[19]||(o[19]=e("h1",{id:"chromebook-如何双启动-ubuntu-17-04-gnome-和-chrome-os",tabindex:"-1"},[t("Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS "),e("a",{class:"header-anchor",href:"#chromebook-如何双启动-ubuntu-17-04-gnome-和-chrome-os","aria-label":"Permalink to “Chromebook 如何双启动：Ubuntu 17.04 GNOME 和 Chrome OS”"},"​")],-1)),o[20]||(o[20]=e("blockquote",null,[e("p",null,"本教程使用著名的 Crouton 安装器")],-1)),o[21]||(o[21]=e("p",null,[e("img",{src:"http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-2.jpg",alt:"Ubuntu 17.04 with GNOME 3.24 running on Acer Chromebook 11 (C740)"})],-1)),e("p",null,[o[1]||(o[1]=t("在去年我拿到我的 Acer Chromebook 11 (C740) 时，我写了一篇教程教你们如何",-1)),s(n,{href:"http://news.softpedia.com/news/here-s-how-to-install-any-linux-operating-system-on-your-chromebook-506212.shtml"},{default:r(()=>[...o[0]||(o[0]=[t("如何移除 Google Chrome OS 并根据你的选择安装一个 GNU/Linux 发行版",-1)])]),_:1}),o[2]||(o[2]=t("，但是很快我觉得没意思了。",-1))]),o[22]||(o[22]=u('<p>因此几个月之后，我使用了 Google 在网站上提供的恢复镜像重新安装了 Chrome OS，我写入了 USB 并从 Chromebook 启动。最近，我又感到无聊了，因此我决定使用 Crouton 在我的 Acer Chromebook 11 (C740) 上安装 Ubuntu。</p><p>为什么？因为在一次会议中来的一位朋友带了他的笔记本，一台 Dell Chromebook 13，在上面他运行了 Ubuntu Linux 还有 Chrome OS。看他用快捷键在两个操作系统之间切换很酷，这让我也想这么做。</p><p>现在有很多教程解释如何安装不同的发行版 Ubuntu、Debian 或者 Kali Linux（这些是当前 Crouton 安装器支持的 GNU/Linux 发行版），但是我想要运行最新的 Ubuntu，当前是 Ubuntu 17.04 (Zesty Zapus)，它有 GNOME 3.24 桌面环境。</p><h3 id="如何启用开发者模式并下载-crouton" tabindex="-1">如何启用开发者模式并下载 Crouton <a class="header-anchor" href="#如何启用开发者模式并下载-crouton" aria-label="Permalink to “如何启用开发者模式并下载 Crouton”">​</a></h3><p>当我询问我的朋友他在他的 Chromebook 上运行的是什么 Ubuntu 时，回答是 Ubuntu 14.04 LTS (Trusty Tahr)，我不得不承认这让我有点失望。我回家后立刻拿出我的 Chromebook 并尝试看看我是否能运行带有桌面环境的 Ubuntu 17.04。</p><p>我做的第一件事情是将我的 Chromebook 变成开发者模式。为此，你需要关闭你的 Chromebook 但不关闭翻盖，接着同时按住 <code>ESC</code>、<code>Refresh</code> 和 <code>Power</code> 键几秒直到进入恢复模式，这会擦除 Chromebook 上的所有数据。</p>',6)),e("p",null,[o[4]||(o[4]=t("进入开发者模式会花费你几分钟，所以耐心点。当准备完成后，你需要登录你的 Google 账户，并设置各种东西，比如壁纸或者头像之类。现在你进入开发者模式了，在你的 Chromebook 中访问这篇教程并",-1)),s(n,{href:"https://goo.gl/fd3zc"},{default:r(()=>[...o[3]||(o[3]=[t("下载 Crouton",-1)])]),_:1}),o[5]||(o[5]=t("，它会保存在下载文件夹中。",-1))]),o[23]||(o[23]=u(`<h3 id="如何使用-crouton-安装带有-gnome-3-24-的-ubuntu-17-04" tabindex="-1">如何使用 Crouton 安装带有 GNOME 3.24 的 Ubuntu 17.04 <a class="header-anchor" href="#如何使用-crouton-安装带有-gnome-3-24-的-ubuntu-17-04" aria-label="Permalink to “如何使用 Crouton 安装带有 GNOME 3.24 的 Ubuntu 17.04”">​</a></h3><p>现在打开 Google Chrome 并按下 <code>CTRL+ALT+T</code> 打开 Chrome OS 的终端模拟器，它叫做 crosh。在命令提示符中，输入 <code>shell</code> 命令，按下回车进入 Linux shell。让我们看看 Crouton 能为我们做什么。</p><p>这有两个命令（下面列出的），你可以运行它们查看 Crouton 支持的 GNU/Linux 发行版和桌面环境，并且我可以告诉你这可以安装 Debian 7 “Wheezy”、Debian 8 “Jessie”、Debian 9 “Stretch” 和 Debian Sid、Kali Linux 滚动版还有 Ubuntu 12.04 LTS、Ubuntu 14.04 LTS 和 Ubuntu 16.04 LTS 等等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh -e /Downloads/crouton -r list -  ### 会列出支持的发行版 </span></span>
<span class="line"><span>sh -e /Downloads/crouton -t list -  ### 会列出支持的桌面</span></span></code></pre></div><p>Crouton 也会列出一系列 Debian、Kali 和 Ubuntu 的旧发行版，但它们在上游被中止支持了（这些的名字后面都被标记了感叹号），并且因为安全风险你不应该安装它们，还有两个尚未支持的 Ubuntu 版本，Ubuntu 16.10 和 Ubuntu 17.04。</p><p>Crouton 开发者说这些“不支持”的 Ubuntu 版本用一些方法可能也可以使用，但是我试了一下并使用下面的命令安装了带有 GNOME 3.24 桌面环境（没有额外的应用）的 Ubuntu 17.04 (Zesty Zapus)。我使用 <code>-e</code> 参数来加密安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh -e /Downloads/crouton -e -r zesty -t gnome</span></span></code></pre></div><p>将所有的都下载下来并安装在 Crouton 在你的 Chromebook 中创建的 chroot 环境中会花费一些时间，因此再说一次，请耐心。当一切完成后，你会知道，并且你能通过在 shell 中运行下面的命令启动 Ubuntu 17.04。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo startgnome</span></span></code></pre></div><p>瞧！我在我的旧 Acer Chromebook 11 (C740) 上运行着带有 GNOME 3.24 桌面环境的 Ubuntu 17.04 (Zesty Zapus)，这笔记本 Google 还尚未支持 Android 程序。最棒的部分是我能够使用 <code>CTRL+ALT+Shift</code>+<code>Back</code>/<code>Forward</code> 键盘快捷键快速在 Chrome OS 和 Ubuntu 17.04 之间切换。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-3.jpg" alt="GNOME 3.24 desktop - System menu"></p><p>作为这篇笔记的结尾，我想提醒你注意，由于 Chromebook 现在始终处于开发人员模式，所以当电池电量耗尽、打开或关闭设备时，你会一直看到一个警告，显示 “OS verification is OFF - Press SPACE to re-enable”，当你看到它时，请按 <code>CTRL+D</code>。玩得开心！</p><p><img src="http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-4.jpg" alt="GNOME 3.24 desktop - Calendar applet"></p><p><img src="http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-5.jpg" alt="GNOME 3.24 desktop - Overview mode"></p><hr>`,15)),e("p",null,[o[7]||(o[7]=t("via: ",-1)),s(n,{href:"http://news.softpedia.com/news/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624.shtml"},{default:r(()=>[...o[6]||(o[6]=[t("http://news.softpedia.com/news/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624.shtml",-1)])]),_:1})]),e("p",null,[o[11]||(o[11]=t("作者：",-1)),s(n,{href:"http://news.softpedia.com/editors/browse/marius-nestor"},{default:r(()=>[...o[8]||(o[8]=[t("Marius Nestor",-1)])]),_:1}),o[12]||(o[12]=t(" 译者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:r(()=>[...o[9]||(o[9]=[t("geekpi",-1)])]),_:1}),o[13]||(o[13]=t(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:r(()=>[...o[10]||(o[10]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[16]||(o[16]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[14]||(o[14]=[t("LCTT",-1)])]),_:1}),o[17]||(o[17]=t(" 原创编译，",-1)),s(n,{href:"https://linux.cn/"},{default:r(()=>[...o[15]||(o[15]=[t("Linux中国",-1)])]),_:1}),o[18]||(o[18]=t(" 荣誉推出",-1))])])}const O=i(h,[["render",m]]);export{T as __pageData,O as default};
